#include <jni.h>
#include <string>
#include <vector>
#include <cstring>
#include <mutex>
#include <unordered_map>
#include <functional>
#include <httplib.h>

static JavaVM* g_jvm = nullptr;
static std::mutex g_env_mutex;
static std::unordered_map<std::thread::id, JNIEnv*> g_env_cache;

class JNILocalFrameGuard {
    JNIEnv* env_;
    int capacity_;
public:
    JNILocalFrameGuard(JNIEnv* env, int capacity) : env_(env), capacity_(capacity) {
        env_->PushLocalFrame(capacity);
    }
    ~JNILocalFrameGuard() {
        env_->PopLocalFrame(nullptr);
    }
};

JNIEnv* get_thread_env() {
    JNIEnv* env = nullptr;
    auto tid = std::this_thread::get_id();
    {
        std::lock_guard<std::mutex> lock(g_env_mutex);
        auto it = g_env_cache.find(tid);
        if (it != g_env_cache.end()) return it->second;
    }
    g_jvm->AttachCurrentThread((void**)&env, nullptr);
    {
        std::lock_guard<std::mutex> lock(g_env_mutex);
        g_env_cache[tid] = env;
    }
    return env;
}

struct UploadMetadata {
    std::string filename;
    std::string content_type;
    size_t file_size;
    unsigned char sha256[32];
};

class ScanResult {
public:
    bool is_safe;
    std::string threat_name;
    int severity;
};

ScanResult invoke_java_scanner(JNIEnv* env, const std::vector<unsigned char>& data, const UploadMetadata& meta) {
    JNILocalFrameGuard frame(env, 32);

    jclass scannerClass = env->FindClass("com/security/FileScanner");
    if (!scannerClass) return {false, "ClassNotFound", 10};

    jmethodID scanMethod = env->GetStaticMethodID(scannerClass, "scanUpload", "([BLjava/lang/String;I)Lcom/security/ScanResult;");
    if (!scanMethod) return {false, "MethodNotFound", 10};

    jbyteArray jdata = env->NewByteArray(static_cast<jsize>(data.size()));
    if (!jdata) {
        env->ExceptionClear();
        return {false, "AllocFailed", 10};
    }
    env->SetByteArrayRegion(jdata, 0, static_cast<jsize>(data.size()), reinterpret_cast<const jbyte*>(data.data()));

    jstring jfilename = env->NewStringUTF(meta.filename.c_str());
    jint jsize = static_cast<jint>(meta.file_size);

    jobject result = env->CallStaticObjectMethod(scannerClass, scanMethod, jdata, jfilename, jsize);
    if (env->ExceptionCheck()) {
        env->ExceptionClear();
        return {false, "ScanException", 10};
    }
    if (!result) {
        return {false, "NullScanResult", 10};
    }

    jclass resultClass = env->GetObjectClass(result);
    if (!resultClass) {
        return {false, "ResultClassNotFound", 10};
    }
    jfieldID safeField = env->GetFieldID(resultClass, "isSafe", "Z");
    jfieldID threatField = env->GetFieldID(resultClass, "threatName", "Ljava/lang/String;");
    if (!safeField || !threatField) {
        env->ExceptionClear();
        return {false, "FieldNotFound", 10};
    }

    ScanResult sr;
    sr.is_safe = env->GetBooleanField(result, safeField);
    jstring jthreat = (jstring)env->GetObjectField(result, threatField);
    if (jthreat) {
        const char* threat_chars = env->GetStringUTFChars(jthreat, nullptr);
        if (threat_chars) {
            sr.threat_name = threat_chars;
            env->ReleaseStringUTFChars(jthreat, threat_chars);
        }
    }
    sr.severity = 0;
    return sr;
}

std::string sanitize_filename(const std::string& input) {
    std::string result;
    result.reserve(input.size());
    for (char c : input) {
        if (c == '/' || c == '\\' || c == '\0') continue;
        if (c == '.' && result.size() > 0 && result.back() == '.') continue;
        result += c;
    }
    return result;
}

bool validate_content_type(const std::string& ct) {
    static const std::vector<std::string> allowed = {
        "application/pdf", "image/png", "image/jpeg", "text/plain"
    };
    for (const auto& a : allowed) {
        if (ct == a) return true;
    }
    return false;
}

std::string escape_json_string(const std::string& input) {
    std::string output;
    output.reserve(input.size() + 16);
    for (char c : input) {
        switch (c) {
            case '"': output += "\\\""; break;
            case '\\': output += "\\\\"; break;
            case '\n': output += "\\n"; break;
            case '\r': output += "\\r"; break;
            case '\t': output += "\\t"; break;
            default:
                if (static_cast<unsigned char>(c) < 0x20) {
                    char buf[8];
                    snprintf(buf, sizeof(buf), "\\u%04x", (unsigned char)c);
                    output += buf;
                } else {
                    output += c;
                }
        }
    }
    return output;
}

void handle_upload(const httplib::Request& req, httplib::Response& res) {
    if (!req.has_file("file")) {
        res.status = 400;
        res.set_content("{\"error\":\"no file\"}", "application/json");
        return;
    }

    auto file = req.get_file_value("file");
    std::string safe_name = sanitize_filename(file.filename);

    if (safe_name.empty() || safe_name.size() > 255) {
        res.status = 400;
        res.set_content("{\"error\":\"invalid filename\"}", "application/json");
        return;
    }

    if (!validate_content_type(file.content_type)) {
        res.status = 415;
        res.set_content("{\"error\":\"unsupported type\"}", "application/json");
        return;
    }

    constexpr size_t MAX_SIZE = 10 * 1024 * 1024;
    if (file.content.size() > MAX_SIZE) {
        res.status = 413;
        res.set_content("{\"error\":\"too large\"}", "application/json");
        return;
    }

    UploadMetadata meta;
    meta.filename = safe_name;
    meta.content_type = file.content_type;
    meta.file_size = file.content.size();

    std::vector<unsigned char> data(file.content.begin(), file.content.end());

    JNIEnv* env = get_thread_env();
    ScanResult scan = invoke_java_scanner(env, data, meta);

    if (scan.is_safe) {
        res.status = 200;
        res.set_content("{\"status\":\"accepted\",\"file\":\"" + escape_json_string(safe_name) + "\"}", "application/json");
    } else {
        res.status = 403;
        res.set_content("{\"status\":\"rejected\",\"threat\":\"" + escape_json_string(scan.threat_name) + "\"}", "application/json");
    }
}

int main() {
    JavaVMInitArgs vm_args;
    JavaVMOption options[1];
    options[0].optionString = (char*)"-Djava.class.path=./scanner.jar";
    vm_args.version = JNI_VERSION_1_8;
    vm_args.nOptions = 1;
    vm_args.options = options;
    vm_args.ignoreUnrecognized = JNI_FALSE;

    JNIEnv* env;
    JNI_CreateJavaVM(&g_jvm, (void**)&env, &vm_args);

    httplib::Server svr;
    svr.Post("/api/upload", handle_upload);
    svr.listen("127.0.0.1", 8443);

    g_jvm->DestroyJavaVM();
    return 0;
}
